#!/bin/bash
# Fifth round: final faction rosters. Each sheet refines the round-four sheet it is given (same look, same units),
# sharpens the differences between units, adds the faction's boss, and steers designs further from existing games.
CX="/c/Program Files/WindowsApps/OpenAI.Codex_26.1106.6628.0_x64__2p2nqsd0c76g0/app/resources/codex.exe"
cd "$(dirname "$0")"
mkdir -p concepts
cd concepts
COMMON="Art direction: grounded, serious science-fantasy enemy design for a premium first-person shooter. Believable anatomy, menacing and dignified, weathered functional materials, a restrained palette of two main colours plus ONE glowing accent colour. Not cartoony, not cute, not toy-like. Rendered as final, production-quality in-game 3D character models with crisp detail. Layout: a final enemy faction roster sheet on a plain dark navy background, landscape 16:9, exactly seven units in one row, drawn to a consistent scale relative to each other so the size differences are real, evenly spaced with clear gaps, neutral poses, the boss last on the right. Every unit must have a completely different silhouette and body plan, instantly distinguishable as a black shape. They belong together only through shared materials, colours, ornament and the same glowing accent. Original designs only: do not resemble any existing video game's characters. No text, no labels, no logos, no borders, no environment."
gen () { # name reference prompt
  [ -f "$1.png" ] && { echo "skip $1"; return; }
  "$CX" exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to generate one image: $3 $COMMON Save the resulting PNG into the current directory as $1.png. Reply with only the saved file path." -i "$2" < /dev/null > "$1.log" 2>&1
  [ -f "$1.png" ] && echo "ok $1" || echo "FAIL $1"
}
KEEP="The attached image is the approved previous version of this faction's roster. Keep its look, materials, colours and its six units recognisably the same, redrawn cleaner and more refined, with the changes listed, and add a seventh unit, the faction's boss."
gen varrik5 varrik4.png "The Varrik: a once-noble spacefaring people fallen into piracy. Bone-white masks and plates, charcoal leather, deep teal cloth, electric-blue energy accent. $KEEP Units left to right: (1) RUNT, small hunched scavenger with a knife. (2) RAIDER, tall gaunt long-necked rifleman. (3) HOUND, lean masked four-legged hunting beast. (4) KITE, flying sailcloth scout drone with a blue lamp eye, airborne. (5) CAPTAIN, tall broad caped noble with energy sabre and blue energy buckler. (6) STRIDER, towering piloted tripod walker with a cannon and banners. (7) BOSS, the CORSAIR QUEEN: a very tall, regal, slender four-horned matriarch, half again the Captain's height, in a long layered teal mantle and an ornate bone-white crown-mask, wielding a huge crescent-bladed energy glaive, with two small Kite drones tethered to her shoulders by cables. Changes: make the Runt even smaller and more feral; give the Captain a clearly heavier, wider build than the Raider." &
gen ordon5 ordon4.png "The Ordon Legion: the disciplined army of an expansionist interstellar empire. Deep bronze and dark green armour plate over black, glowing amber accent. $KEEP Units left to right: (1) AUXILIARY, small thin conscript sniper of a slighter species. (2) LEGIONARY, massive heavy infantryman. (3) BULWARK, trooper behind an enormous tower shield. (4) WAR BEAST, armoured tusked four-legged charger. (5) GUNSHIP DRONE, hovering wedge-shaped flying machine, airborne. (6) COLOSSUS, towering siege unit. (7) BOSS, the LEGATE: a commander taller than a Legionary but leaner and more upright, with a great transverse bronze helmet crest, a long dark green cloak, a jump pack with amber thrusters, a heavy power maul in one hand and a banner standard on its back. Changes, to make the faction more original and its units less alike: give all Ordon helmets a distinctive tall narrow shape with a single vertical amber visor slit and a bronze fin crest, and give their armour overlapping segmented plates like a crustacean shell rather than blocky panels; redesign the Colossus as a hunched, top-heavy giant with a sunken head between enormous shoulders and cannons built into both forearms instead of hands, so it is not just a larger Legionary; make the Bulwark squat and very wide." &
gen hollowed5 hollowed4.png "The Hollowed: an ancient cult risen from the deep, spreading a parasitic crystal growth. Aged bone-coloured shell, near-black flesh, dark wine-red cloth, glowing violet crystal accent. $KEEP Units left to right: (1) CRAWLER, small feral creature on all fours. (2) HUSK, bloated carrier with a huge glowing crystal sac for a torso. (3) ACOLYTE, thin robed figure with a ritual staff. (4) REAVER, tall armoured warrior. (5) SEER, floating legless caster with a halo of orbiting crystal shards. (6) BEHEMOTH, enormous knuckle-walking brute with a ridge of crystals on its back. (7) BOSS, the DROWNED CHOIR: a towering horror formed of three robed torsos fused back to back on one wide trailing body, six arms raised, a great ring of violet crystal turning slowly above their heads, drifting just above the ground. Changes, to make the faction more original: every Hollowed head is a smooth, faceless, elongated shell with no eyes or mouth and one glowing violet crystal hanging from the brow like a lure; their shell has the layered, fluted texture of deep-sea shells and coral, not human bones or skulls; replace the previous sword-and-shield knight with the REAVER, whose forearms end in two long curved crystal blades instead of hands, hunched forward in a predatory stance." &
gen warden5 warden4.png "The Wardens: ancient guardian war-machines built by a vanished civilisation. Carved black stone plates and dark burnished metal, thin pale-gold engraved lines, glowing jade-green light. $KEEP Units left to right: (1) MITE, tiny six-legged stone beetle machine. (2) SENTRY, slim upright humanoid frame. (3) LANCER, tall four-legged machine carrying one long beam cannon. (4) WATCHER, hovering spindle with orbiting curved plates and a jade eye, airborne. (5) PRAETORIAN, very large wide humanoid frame with a fan of stone plates, a hard-light shield and a beam glaive. (6) OBELISK, colossal floating machine of separate stone slabs around a blazing jade core. (7) BOSS, the ARCHITECT: a tall, serene, many-armed stone figure seated cross-legged on nothing, floating, with six slender arms spread in a fan, each hand holding a small hovering geometric solid of jade light, a wide flat ring of engraved stone turning behind it like a halo. Changes: make the Sentry more distinctive with a tall narrow triangular head-plate and one arm that is entirely a beam emitter; show the Mite a little larger so it reads." &
gen tideborn5 ../refs/enemy.png "The Tideborn: the planet's native apex predators, amphibious reptilian pack hunters. The attached image is the approved existing Tideborn STALKER: keep its species, navy-blue armoured hide, orange neck frill and crested head as the faction's look. Navy-blue plated hide, orange frills and fins, glowing cyan accent. Units left to right: (1) BURSTER, a small swollen sprinting runt with a glowing orange volatile sac on its back. (2) STALKER, the attached creature, an upright clawed pack hunter. (3) SPITTER, a tall thin long-necked cousin with a wide tube mouth and a glowing cyan-green throat sac. (4) SKIMMER, a flying creature like a manta ray with a wide flat finned body, a long whip tail and an orange underside, airborne. (5) SHELLBACK, a low, very wide four-legged armoured creature like a giant horned turtle-crab with a thick domed navy shell and a small frilled head. (6) MATRIARCH, a long serpentine swimmer with a rearing upper body, two clawed arms, a huge fan frill and a coiled tail instead of legs. (7) BOSS, the TIDE ALPHA: a towering hulking brute with massive shoulders and forearms, a wide spiked orange frill, and glowing orange vents between dark crimson and near-black armour plates." &
wait
echo ALLDONE
